import {routeHitsObstacles,routeNodeObstacles} from './wire-obstacles.js';
import {commonRouteBounds,insideRouteBounds,routeRecordBounds} from './route-bounds.js';
import {routeConflict} from './wire-spacing.js';
import {polylinePoints} from './wire-crossings.js';
import {routeCable,pathData} from './geometry.js';
import {resolveManualRoute,moveRouteSegment,moveRouteBend,insertRoutePoint,removeRoutePoint} from './manual-route.js';
const copy=p=>p.map(({x,y})=>({x,y}));
export function installRouteEditor(canvas){
 const ns='http://www.w3.org/2000/svg',tools=document.createElement('div');tools.className='route-tools';tools.id='route-tools';tools.hidden=true;tools.setAttribute('aria-label','Прокладка выбранного кабеля');tools.innerHTML='<span id="route-mode"></span><button id="route-edit">Изменить прокладку</button><small id="route-help" hidden>Двойной клик — точка · ПКМ по точке — удалить</small><button id="route-auto" hidden>Автопрокладка</button><button id="route-done" hidden>Готово</button><button id="route-close" aria-label="Закрыть панель кабеля">×</button>';canvas.viewport.parentElement.append(tools);
 tools.querySelector('#route-edit').onclick=()=>{canvas.editingWireRoute=canvas.selectedWireRoute;canvas.lastRouteClick=null;canvas.cancelCamera?.();canvas.pauseTraffic?.();canvas.drawRouteHandles()};
 tools.querySelector('#route-auto').onclick=()=>{const key=canvas.selectedWireRoute,s=canvas.getState();s.wireRoutes=(s.wireRoutes||[]).filter(r=>r.id!==key);canvas.commit();canvas.notify('Возвращена автоматическая прокладка. ↶ — отменить')};
 tools.querySelector('#route-done').onclick=()=>{canvas.editingWireRoute=null;canvas.lastRouteClick=null;canvas.render()};
 tools.querySelector('#route-close').onclick=()=>{canvas.selectedWireRoute=null;canvas.editingWireRoute=null;canvas.render()};
 const point=e=>{const r=canvas.world.getBoundingClientRect();return{x:(e.clientX-r.left)/canvas.zoom,y:(e.clientY-r.top)/canvas.zoom}};
 canvas.svg.addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-route-handle]');if(!handle||e.button!==0)return;e.preventDefault();e.stopPropagation();canvas.cancelCamera?.();canvas.pauseTraffic?.();const record=canvas.routeRecords?.get(canvas.selectedWireRoute);if(!record)return;canvas.routeDrag={id:record.id,kind:handle.dataset.routeHandle,index:Number(handle.dataset.index),start:point(e),points:copy(record.points),moved:false}},true);
 const savePoints=(id,points,message)=>{if(points.length>96)throw Error('Максимум 96 точек');if(routeHitsObstacles(points,canvas.routeRecords.get(id)?.obstacles||[]))throw Error('Маршрут пересекает ноду. Отведите участок вокруг устройства');if(!insideRouteBounds(points,canvas.routeRecords.get(id)?.bounds))throw Error('Маршрут должен оставаться внутри общей родительской ноды');const state=canvas.getState();state.wireRoutes=(state.wireRoutes||[]).filter(r=>r.id!==id);state.wireRoutes.push({id,points});canvas.commit();canvas.notify(message+' · ↶ — отменить')};
 const addPoint=(e,id)=>{e.preventDefault();e.stopImmediatePropagation();if(performance.now()<(canvas.pointInsertUntil||0))return;const record=canvas.routeRecords.get(id);if(!record)return;try{savePoints(id,insertRoutePoint(record.points,point(e)),'Точка добавлена');canvas.pointInsertUntil=performance.now()+300}catch(err){canvas.notify(err.message)}};
 canvas.svg.addEventListener('dblclick',e=>{const id=e.target.closest('[data-route-key]')?.dataset.routeKey||(e.target.closest('[data-route-handle]')&&canvas.selectedWireRoute);if(id&&canvas.editingWireRoute===id)addPoint(e,id)},true);
 canvas.svg.addEventListener('contextmenu',e=>{const handle=e.target.closest('[data-route-handle="bend"]');if(!handle)return;e.preventDefault();e.stopImmediatePropagation();const menu=document.getElementById('menu');canvas.removePointTarget={id:canvas.selectedWireRoute,index:Number(handle.dataset.index)};menu.innerHTML='<div class="menutitle">Точка маршрута</div><button data-delete-route-point="true">× Удалить точку</button><div class="menutitle">Соседние участки соединятся под прямыми углами. ↶ — отменить.</div>';menu.hidden=false;menu.style.left=Math.max(8,Math.min(e.clientX,innerWidth-290))+'px';menu.style.top=Math.max(8,Math.min(e.clientY,innerHeight-140))+'px'},true);
 document.getElementById('menu').addEventListener('click',e=>{if(!e.target.closest('[data-delete-route-point]'))return;e.stopPropagation();const menu=document.getElementById('menu'),target=canvas.removePointTarget,record=target&&canvas.routeRecords.get(target.id);menu.hidden=true;if(!record)return;try{const points=removeRoutePoint(record.points,target.index),others=[...canvas.routeRecords.values()].filter(r=>r.id!==target.id).map(r=>r.points);if(routeConflict(points,others))throw Error('Удаление создаст наложение кабелей. Сначала отведите соседний участок.');savePoints(target.id,points,'Точка удалена')}catch(err){canvas.notify(err.message)}});
 canvas.svg.addEventListener('click',e=>{const key=e.target.closest('[data-route-key]')?.dataset.routeKey||(e.target.closest('[data-route-handle]')&&canvas.selectedWireRoute),editing=key&&canvas.editingWireRoute===key,last=canvas.lastRouteClick;if(editing&&last&&last.id===key&&performance.now()-last.time<400&&Math.hypot(e.clientX-last.x,e.clientY-last.y)<6){canvas.lastRouteClick=null;addPoint(e,key);return}if(editing)canvas.lastRouteClick={id:key,time:performance.now(),x:e.clientX,y:e.clientY};if(e.target.closest('[data-route-handle]')||performance.now()<(canvas.ignoreClickUntil||0)){e.preventDefault();e.stopImmediatePropagation();return}const group=e.target.closest('[data-route-key]');if(group){canvas.cancelCamera?.();canvas.pauseTraffic?.();if(canvas.selectedWireRoute!==key){canvas.editingWireRoute=null;canvas.lastRouteClick=null}canvas.selectedWireRoute=key;canvas.drawRouteHandles();if(!group.dataset.cable&&!e.target.closest('[data-binding]')){e.stopPropagation();canvas.drawRouteHandles()}}},true);
 document.addEventListener('keydown',e=>{if(e.key!=='Escape'||e.target.matches('input,textarea,select'))return;if(canvas.routeDrag){e.preventDefault();e.stopImmediatePropagation();canvas.routeDrag=null;canvas.routePreview=null;canvas.render()}else{canvas.selectedWireRoute=null;canvas.editingWireRoute=null}},true);
 canvas.routeLaneConstraints=function(id){return[...(this.wireLanes||[]),...(this.reservedRouteLanes||[]).filter(r=>r.id!==id).map(r=>r.points)]};
 canvas.spacedRoute=function(a,b,obstacles,lane,id){const saved=(this.getState().wireRoutes||[]).find(r=>r.id===id);const bounds=commonRouteBounds(this.g,a,b),manual=saved&&resolveManualRoute(saved,a,b);if(manual&&!a.proxy&&!b.proxy&&insideRouteBounds(manual,bounds)&&!routeHitsObstacles(manual,obstacles))return{points:manual,blocked:false};const safeObstacles=obstacles.map(r=>bounds&&r.x===bounds.x&&r.y===bounds.y&&(a.owner===bounds.id||b.owner===bounds.id)?{...r,h:48}:r);return routeCable(a,b,safeObstacles,lane,false,this.routeLaneConstraints(id),bounds)};
 canvas.prepareRouteLanes=function(){const s=this.getState(),keys=new Set([...s.links.map(l=>'link:'+l.id),...s.nodes.filter(n=>n.type==='bridge').flatMap(n=>(n.members||[]).map(p=>'binding:member:'+n.id+':'+p)),...s.nodes.filter(n=>n.services.http?.publishHost).flatMap(n=>['dnat','route'].map(phase=>'kernel:'+n.id+':'+phase))]);this.reservedRouteLanes=(s.wireRoutes||[]).filter(r=>keys.has(r.id)).map(r=>{const l=s.links.find(l=>'link:'+l.id===r.id),a=l&&this.g.ports.get(l.a),b=l&&this.g.ports.get(l.b);return a&&b?{id:r.id,points:resolveManualRoute(r,a,b)}:r})};
 canvas.applyManualRoutes=function(){this.routeRecords=new Map();const s=this.getState();for(const source of this.svg.querySelectorAll('.cable > .wire,.kernel-wire > .kernel-line')){const group=source.parentElement,id=group.dataset.cable?'link:'+group.dataset.cable:group.dataset.bindingId?'binding:'+group.dataset.bindingId:'kernel:'+group.dataset.kernelId+':'+group.dataset.kernelPhase,automatic=polylinePoints(source.getAttribute('d'));if(automatic.length<2)continue;const saved=(s.wireRoutes||[]).find(r=>r.id===id),proxy=[source.dataset.start,source.dataset.end].some(id=>id&&this.g.ports.get(id)?.proxy);let points=saved&&!proxy?resolveManualRoute(saved,automatic[0],automatic.at(-1)):automatic;if(this.routePreview?.id===id)points=this.routePreview.points;const bounds=routeRecordBounds(this,source),obstacles=routeNodeObstacles(this,source),suspended=!insideRouteBounds(points,bounds)||routeHitsObstacles(points,obstacles);if(suspended)points=automatic;group.dataset.routeKey=id;group.classList.toggle('manual-wire',!!saved);group.classList.toggle('route-collision',this.routePreview?.id===id&&this.routePreview.conflict);const d=pathData(points);source.setAttribute('d',d);group.querySelector('.wire-hit')?.setAttribute('d',d);this.routeRecords.set(id,{id,points,automatic,manual:!!saved,source,bounds,obstacles,suspended})}};
 canvas.drawRouteHandles=function(){this.svg.querySelector('#route-handles')?.remove();const r=this.routeRecords?.get(this.selectedWireRoute);tools.hidden=!r;if(!r){this.editingWireRoute=null;return}const editing=this.editingWireRoute===r.id;tools.classList.toggle('route-editing',editing);tools.querySelector('#route-edit').hidden=editing;for(const id of ['route-help','route-auto','route-done'])tools.querySelector('#'+id).hidden=!editing;tools.querySelector('#route-mode').textContent=r.suspended?'Ручная трасса не помещается · показана автоматическая':r.manual||this.routePreview?'Ручная прокладка':editing?'Автопрокладка · тяните ручки':'Автоматическая прокладка';tools.querySelector('#route-auto').disabled=!r.manual;if(!editing)return;const group=document.createElementNS(ns,'g');group.id='route-handles';
  const handle=(kind,index,x,y,horizontal)=>{const el=document.createElementNS(ns,kind==='bend'?'circle':'rect'),size=5/this.zoom;el.dataset.routeHandle=kind;el.dataset.index=index;if(kind==='bend'){el.setAttribute('cx',x);el.setAttribute('cy',y);el.setAttribute('r',size)}else{el.setAttribute('x',x-size);el.setAttribute('y',y-size);el.setAttribute('width',2*size);el.setAttribute('height',2*size);el.style.cursor=horizontal?'ns-resize':'ew-resize'}const title=document.createElementNS(ns,'title');title.textContent=kind==='bend'?'Тяните точку · ПКМ — удалить':'Тяните участок поперёк линии';el.append(title);group.append(el)};
  r.points.forEach((p,i)=>{if(i>0&&i<r.points.length-1){const a=r.points[i-1],b=r.points[i+1];handle('bend',i,p.x,p.y)}if(i<r.points.length-1){const b=r.points[i+1];if(Math.hypot(p.x-b.x,p.y-b.y)*this.zoom>28)handle('segment',i,(p.x+b.x)/2,(p.y+b.y)/2,p.y===b.y)}});this.svg.append(group);
 };
 canvas.moveRoute=function(e){const drag=this.routeDrag;if(!drag)return false;const now=point(e),dx=now.x-drag.start.x,dy=now.y-drag.start.y;if(Math.hypot(dx,dy)*this.zoom<2&&!drag.moved)return true;drag.moved=true;const p=drag.points[drag.index];let points=drag.kind==='bend'?moveRouteBend(drag.points,drag.index,{x:Math.max(0,p.x+dx),y:Math.max(0,p.y+dy)}):moveRouteSegment(drag.points,drag.index,Math.max(0,p.y===drag.points[drag.index+1].y?p.y+dy:p.x+dx));if(points.length>96){this.notify('Максимум 96 точек. Упростите маршрут или верните автопрокладку.');return true}const others=[...this.routeRecords.values()].filter(r=>r.id!==drag.id).map(r=>r.points);this.routePreview={id:drag.id,points,conflict:routeConflict(points,others)||!insideRouteBounds(points,this.routeRecords.get(drag.id)?.bounds)||routeHitsObstacles(points,this.routeRecords.get(drag.id)?.obstacles||[])};this.schedule();return true};
 canvas.finishRoute=function(){const drag=this.routeDrag;if(!drag)return false;this.routeDrag=null;const preview=this.routePreview;this.routePreview=null;if(drag.moved&&preview?.conflict){this.render();this.notify('Прокладка не сохранена: параллельные кабели должны быть разведены минимум на 3 толщины линии. Красный участок накладывается на кабель, пересекает устройство или выходит за границы родительской ноды.');return true}if(drag.moved&&preview){const s=this.getState();s.wireRoutes=(s.wireRoutes||[]).filter(r=>r.id!==drag.id);s.wireRoutes.push({id:drag.id,points:copy(preview.points)});this.ignoreClickUntil=performance.now()+250;this.commit();this.notify('Прокладка сохранена. ↶ — отменить')}else this.render();return true};
}
